![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

`SafeSocket` manually implements `Send` and `Sync` without any synchronization, which is unsafe because `zmq::Socket` is not thread-safe. If `ZmqSpikeSink` is shared across threads, concurrent calls to `emit` can cause data races and undefined behavior. A safer and more idiomatic approach is to wrap `SafeSocket` in a `std::sync::Mutex` inside `ZmqSpikeSink`, which automatically provides `Sync` safety.

```rust
    struct SafeSocket(::zmq::Socket);
    unsafe impl Send for SafeSocket {}

    pub struct ZmqSpikeSink {
        socket: std::sync::Mutex<SafeSocket>,
    }

    impl ZmqSpikeSink {
        pub fn new(socket: ::zmq::Socket) -> Self {
            Self {
                socket: std::sync::Mutex::new(SafeSocket(socket)),
            }
        }
    }

    impl SpikeSink for ZmqSpikeSink {
        fn emit(&mut self, spikes: &[SpikeEvent]) -> Result<()> {
            let now = SystemTime::now().duration_since(UNIX_EPOCH)?;
            let tick = now.as_millis() as u64;

            let corpus_spikes: Vec<CorpusSpikeEvent> = spikes
                .iter()
                .map(|e| CorpusSpikeEvent {
                    channel: e.channel,
                    time: e.time,
                    strength: e.strength,
                })
                .collect();

            let msg = SpineMessage::Spikes(SpikeBatch {
                session_id: None,
                batch_id: tick,
                timestamp: now.as_nanos() as u64,
                spikes: corpus_spikes,
                metadata: None,
            });

            let payload = serde_json::to_vec(&msg)?;
            self.socket.lock().unwrap().0.send(payload, 0)?;
            Ok(())
        }
    }
```

